import {parseCaptions,parseRange,continuousBlocks,formatTime} from './core.js';
const $=id=>document.getElementById(id),audio=$('audio');
let db,books=[],active=null,url=null,selection=[],mode=null,A=null,B=null,blocks=[],editing=null,lastSave=0,lastCue=-1,busy=false,openSequence=0,mediaReady=false;
const toast=message=>{$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',5000);};
const size=n=>`${(n/1024/1024).toFixed(1)} MB`;
function request(store,operation,value){return new Promise((resolve,reject)=>{const tx=db.transaction(store,operation==='get'||operation==='getAll'?'readonly':'readwrite');const req=tx.objectStore(store)[operation](value);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Không thể lưu dữ liệu.'));});}
function writeBoth(book,blob){return new Promise((resolve,reject)=>{const tx=db.transaction(['books','files'],'readwrite');tx.objectStore('books').put(book);if(blob)tx.objectStore('files').put({id:book.id,blob});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Không đủ dung lượng lưu trữ.'));});}
async function refresh(){books=(await request('books','getAll')).sort((a,b)=>b.created-a.created);for(const book of books){if(typeof book.caption!=='string'||!book.caption.trim())continue;let parsed;try{parsed=parseCaptions(book.caption);}catch{continue;}if(JSON.stringify(parsed)===JSON.stringify(book.cues))continue;const sameTiming=parsed.length===book.cues.length&&parsed.every((c,i)=>c.start===book.cues[i].start&&c.end===book.cues[i].end);book.cues=parsed;if(!sameTiming)book.selected=[];await request('books','put',book);}renderLibrary();await storage();}
function renderLibrary(){const q=$('search').value.toLocaleLowerCase('vi');$('count').textContent=books.length;$('library').replaceChildren();const filtered=books.filter(b=>b.name.toLocaleLowerCase('vi').includes(q));if(!filtered.length){const p=document.createElement('p');p.style.fontSize='12px';p.textContent=q?'Không tìm thấy bài nghe.':'Thư viện đang chờ bài nghe đầu tiên.';$('library').append(p);}for(const b of filtered){const button=document.createElement('button');button.className='book'+(active?.id===b.id?' active':'');const title=document.createElement('b');title.textContent=b.name;const details=document.createElement('small');details.textContent=`♫ ${formatTime(b.duration)} · ${size(b.size)} · ${b.cues.length?b.cues.length+' đoạn':'Chưa có phụ đề'}`;const progress=document.createElement('div');progress.className='progress';const bar=document.createElement('span');bar.style.width=`${Math.min(100,(b.position||0)/b.duration*100)||0}%`;progress.append(bar);button.append(title,details,progress);button.onclick=()=>safe(()=>openBook(b.id));$('library').append(button);}}
async function storage(){const total=books.reduce((n,b)=>n+b.size,0);$('usage').textContent=`${books.length} bài · ${size(total)} đã lưu`;try{const info=await navigator.storage?.estimate();if(info?.quota)$('usage').textContent+=` · Quota trình duyệt ${size(info.quota)}`;}catch{}}
async function saveProgress(){if(!active||!mediaReady)return;const book={...active};book.position=audio.currentTime||0;book.speed=Number($('speed').value);book.selected=[...selection];book.offset=Number($('offset').value)||0;Object.assign(active,book);await request('books','put',book);const index=books.findIndex(b=>b.id===book.id);if(index>=0)books[index]=book;}
function resetLoop(){mode=null;A=null;B=null;blocks=[];$('abText').textContent='Chọn điểm bắt đầu và kết thúc khi nghe.';$('loop').textContent='Bắt đầu lặp';}
async function openBook(id){const sequence=++openSequence;await saveProgress();const file=await request('files','get',id);if(sequence!==openSequence)return;if(!file?.blob)throw Error('Không tìm thấy audio. Hãy khôi phục từ bản sao lưu.');mediaReady=false;audio.pause();resetLoop();if(url)URL.revokeObjectURL(url);active=books.find(b=>b.id===id);selection=(active.selected||[]).filter(i=>i>=0&&i<active.cues.length);lastCue=-1;url=URL.createObjectURL(file.blob);audio.src=url;audio.playbackRate=active.speed||1;$('speed').value=String(active.speed||1);$('offset').value=active.offset||0;$('title').textContent=active.name;$('details').textContent=`${formatTime(active.duration)} · ${size(active.size)} · ${active.filename}`;$('empty').hidden=true;$('player').hidden=false;$('subtitle').textContent='Bấm phát để bắt đầu nghe.';$('captionTools').hidden=!active.cues.length;$('cueCount').textContent=active.cues.length+' đoạn';renderCues();renderLibrary();const book=active;audio.onloadedmetadata=()=>{if(sequence!==openSequence||active?.id!==book.id)return;audio.currentTime=Math.min(book.position||0,Math.max(0,audio.duration-.05));mediaReady=true;updateCaption();};}
function renderCues(){lastCue=-2;$('cues').replaceChildren();if(!active.cues.length){const p=document.createElement('p');p.textContent='Bài này chưa có phụ đề. Bạn vẫn có thể lặp A–B, hoặc thêm SRT/VTT trong Chỉnh sửa.';$('cues').append(p);}active.cues.forEach((cue,index)=>{const row=document.createElement('div');row.className='cue'+(selection.includes(index)?' selected':'');row.id='cue-'+index;const check=document.createElement('input');check.type='checkbox';check.checked=selection.includes(index);check.setAttribute('aria-label',`Chọn đoạn ${index+1}`);check.onchange=()=>{selection=check.checked?[...selection,index].sort((a,b)=>a-b):selection.filter(n=>n!==index);row.classList.toggle('selected',check.checked);selectionChanged();};const content=document.createElement('div');const timestamp=document.createElement('small');timestamp.textContent=`${index+1} · ${formatTime(cue.start)} – ${formatTime(cue.end)}`;const text=document.createElement('p');text.textContent=cue.text;content.append(timestamp,text);const play=document.createElement('button');play.textContent='▶';play.setAttribute('aria-label',`Nghe đoạn ${index+1}`);play.onclick=()=>{resetLoop();audio.currentTime=Math.max(0,cue.start+(active.offset||0));safe(playAudio);};row.append(check,content,play);$('cues').append(row);});$('selectedCount').textContent=`${selection.length} câu đã chọn`;updateCaption();}
function loopBlocks(){return continuousBlocks(active.cues,selection,active.offset||0,active.duration);}
function selectionChanged(){blocks=loopBlocks();if(!blocks.length&&mode==='sentence'){resetLoop();toast('Không có đoạn hợp lệ để lặp với độ lệch hiện tại.');}$('selectedCount').textContent=`${selection.length} câu đã chọn`;safe(saveProgress);}
async function playAudio(){if(!mediaReady)throw Error('Audio đang tải. Vui lòng chờ một chút.');try{await audio.play();}catch{resetLoop();throw Error('Không thể phát audio. Hãy kiểm tra định dạng file hoặc bấm phát lại.');}}
function updateCaption(){if(!active||!mediaReady)return;const t=audio.currentTime-(active.offset||0);const index=active.cues.findIndex(c=>t>=c.start&&t<c.end);if(index===lastCue)return;if(lastCue>=0)$('cue-'+lastCue)?.classList.remove('current');lastCue=index;if(index>=0){$('subtitle').textContent=active.cues[index].text;const row=$('cue-'+index);row?.classList.add('current');if(row&&!audio.paused){const parent=$('cues');parent.scrollTop+=row.getBoundingClientRect().top-parent.getBoundingClientRect().top-parent.clientHeight/2+row.clientHeight/2;}}else $('subtitle').textContent=active.cues.length?'♪ Khoảng nghỉ ♪':'Nghe theo nhịp riêng của bạn.';}
function enforceLoop(){if(active&&mediaReady&&!audio.paused&&!audio.seeking){const t=audio.currentTime;if(mode==='ab'&&B>A&&(t>=B||t<A-.1))audio.currentTime=A;else if(mode==='sentence'&&blocks.length){const i=blocks.findIndex(b=>t>=b.start-.08&&t<b.end);if(i<0){const next=blocks.find(b=>b.start>t);audio.currentTime=(next||blocks[0]).start;}else if(t>=blocks[i].end-.025)audio.currentTime=blocks[(i+1)%blocks.length].start;}}}
function tick(){enforceLoop();requestAnimationFrame(tick);}
audio.addEventListener('timeupdate',()=>{enforceLoop();updateCaption();if(Date.now()-lastSave>2000){lastSave=Date.now();safe(saveProgress);}});audio.addEventListener('pause',()=>safe(saveProgress));audio.addEventListener('ended',()=>{if(!mediaReady)return;if(mode==='ab'){audio.currentTime=A;safe(playAudio);}else if(mode==='sentence'&&blocks.length){audio.currentTime=blocks[0].start;safe(playAudio);}else safe(saveProgress);});audio.addEventListener('error',()=>{if(active){mediaReady=false;resetLoop();toast('Trình duyệt không đọc được audio này. Hãy thử file MP3 hoặc WAV.');}});
async function safe(fn){try{await fn();}catch(error){toast(error?.name==='QuotaExceededError'?'Thiết bị không đủ dung lượng. Hãy sao lưu và xóa bớt bài.':error.message||'Thao tác chưa thành công.');}}
function showForm(edit=false){editing=edit?active:null;$('uploadForm').reset();$('dialogTitle').textContent=edit?'Chỉnh sửa bài nghe':'Thêm bài nghe';$('name').value=editing?.name||'';$('audioFile').required=!edit;$('audioHint').textContent=edit?'Để trống để giữ audio hiện tại · Tối đa 200 MB':'Chọn file từ thiết bị · Tối đa 200 MB/bài';$('removeCaption').parentElement.hidden=!edit;$('formError').textContent='';$('dialog').showModal();}
$('add').onclick=$('emptyAdd').onclick=()=>showForm();$('edit').onclick=()=>showForm(true);$('close').onclick=()=>{if(!busy)$('dialog').close();};$('dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('audioFile').onchange=()=>{const f=$('audioFile').files[0];if(f&&!$('name').value)$('name').value=f.name.replace(/\.[^.]+$/,'');};
async function durationOf(file){return new Promise((resolve,reject)=>{const a=new Audio(),u=URL.createObjectURL(file);const cleanup=()=>{clearTimeout(timer);a.onloadedmetadata=null;a.onerror=null;a.removeAttribute('src');a.load();URL.revokeObjectURL(u);};const timer=setTimeout(()=>{cleanup();reject(Error('Không đọc được thông tin audio. Hãy thử file khác.'));},15000);a.onloadedmetadata=()=>{const d=a.duration;cleanup();Number.isFinite(d)&&d>0?resolve(d):reject(Error('Thời lượng audio không hợp lệ.'));};a.onerror=()=>{cleanup();reject(Error('Định dạng audio không được trình duyệt hỗ trợ.'));};a.src=u;});}
$('uploadForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('save').disabled=true;$('save').textContent='Đang lưu…';$('formError').textContent='';try{await saveProgress();const file=$('audioFile').files[0],caption=$('captionFile').files[0];if(file?.size>200*1024*1024)throw Error('File audio vượt quá 200 MB.');if(caption?.size>5*1024*1024)throw Error('File phụ đề vượt quá 5 MB.');const name=$('name').value.trim();if(!name)throw Error('Vui lòng nhập tên bài nghe.');const duration=file?await durationOf(file):editing.duration;const text=caption?await caption.text():$('removeCaption').checked?'':editing?.caption||'';const cues=caption?parseCaptions(text):$('removeCaption').checked?[]:editing?.cues||[];if(cues.some(c=>c.start>=duration+.5))throw Error('Phụ đề có đoạn bắt đầu sau khi audio kết thúc. Kiểm tra lại file.');const book={...(editing||{}),id:editing?.id||crypto.randomUUID(),name,created:editing?.created||Date.now(),filename:file?.name||editing?.filename,type:file?.type||editing?.type||'audio/mpeg',size:file?.size||editing?.size,duration,caption:text,cues,position:file?0:editing?.position||0,speed:editing?.speed||1,selected:caption||file||$('removeCaption').checked?[]:editing?.selected||[],offset:editing?.offset||0};const updating=active?.id===book.id;const wasPlaying=updating&&!audio.paused;if(updating){mediaReady=false;audio.pause();book.position=file?0:audio.currentTime;}try{await writeBoth(book,file);}catch(error){if(updating){mediaReady=true;if(wasPlaying)safe(playAudio);}throw error;}if(updating)active=null;await refresh();await openBook(book.id);$('dialog').close();toast(editing?'Đã cập nhật bài nghe.':'Đã lưu bài nghe trên thiết bị.');}catch(error){$('formError').textContent=error.name==='QuotaExceededError'?'Không đủ dung lượng để lưu audio.':error.message;}finally{busy=false;$('save').disabled=false;$('save').textContent='Lưu bài nghe';}};
$('search').oninput=renderLibrary;$('speed').onchange=()=>{audio.playbackRate=Number($('speed').value);safe(saveProgress);};$('back').onclick=()=>audio.currentTime=Math.max(0,audio.currentTime-10);$('forward').onclick=()=>audio.currentTime=Math.min(audio.duration||0,audio.currentTime+10);
$('markA').onclick=()=>{if(!mediaReady){toast('Audio đang tải. Vui lòng chờ.');return;}resetLoop();A=audio.currentTime;$('abText').textContent=`A: ${formatTime(A)} · Nghe tiếp rồi đặt B.`;};$('markB').onclick=()=>{if(A===null){toast('Hãy đặt mốc A trước.');return;}if(audio.currentTime<=A+.1){toast('Mốc B phải sau A ít nhất 0,1 giây.');return;}B=audio.currentTime;mode='ab';$('abText').textContent=`Đang lặp ${formatTime(A)} ↔ ${formatTime(B)}`;audio.currentTime=A;safe(playAudio);};$('clearAB').onclick=resetLoop;
$('loop').onclick=()=>{if(mode==='sentence'){resetLoop();return;}if(!selection.length){toast('Chọn ít nhất một câu để lặp.');return;}if(!mediaReady){toast('Audio đang tải. Vui lòng chờ.');return;}resetLoop();blocks=loopBlocks();if(!blocks.length){toast('Khoảng câu nằm ngoài thời lượng audio.');return;}mode='sentence';$('loop').textContent='Dừng lặp';audio.currentTime=blocks[0].start;safe(playAudio);};$('clear').onclick=()=>{selection=[];selectionChanged();renderCues();};$('choose').onclick=()=>safe(()=>{selection=parseRange($('range').value,active.cues.length);selectionChanged();renderCues();});$('all').onclick=()=>{selection=active.cues.map((_,i)=>i);selectionChanged();renderCues();};$('offset').onchange=()=>{active.offset=Math.max(-120,Math.min(120,Number($('offset').value)||0));$('offset').value=active.offset;selectionChanged();lastCue=-2;document.querySelectorAll('.cue.current').forEach(el=>el.classList.remove('current'));updateCaption();safe(saveProgress);};
$('delete').onclick=()=>safe(async()=>{if(!confirm(`Xóa “${active.name}” và audio trên thiết bị này? Hãy sao lưu nếu cần giữ lại.`))return;const id=active.id;++openSequence;mediaReady=false;audio.onloadedmetadata=null;audio.pause();active=null;audio.removeAttribute('src');audio.load();if(url){URL.revokeObjectURL(url);url=null;}await new Promise((resolve,reject)=>{const tx=db.transaction(['books','files'],'readwrite');tx.objectStore('books').delete(id);tx.objectStore('files').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});$('player').hidden=true;$('empty').hidden=false;resetLoop();await refresh();toast('Đã xóa bài nghe.');});
const toBase64=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});
function fromBase64(value,type){const raw=atob(value),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type});}
$('export').onclick=()=>safe(async()=>{if(!books.length){toast('Thư viện chưa có bài để sao lưu.');return;}$('export').disabled=true;try{await saveProgress();toast('Đang tạo bản sao lưu gồm cả audio…');const rows=[];for(const book of books){const file=await request('files','get',book.id);if(!file?.blob)throw Error('Thiếu audio của bài '+book.name);rows.push({...book,audio:await toBase64(file.blob)});}const blob=new Blob([JSON.stringify({format:'lang-nghe',version:1,books:rows})],{type:'application/json'});const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='lang-nghe-sao-luu-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Đã xuất bản sao lưu. Giữ file này ở nơi an toàn.');}finally{$('export').disabled=false;}});
$('import').onclick=()=>$('backupFile').click();$('backupFile').onchange=()=>safe(async()=>{const file=$('backupFile').files[0];if(!file)return;$('import').disabled=true;try{const data=JSON.parse(await file.text());if(data.format!=='lang-nghe'||data.version!==1||!Array.isArray(data.books)||!data.books.length)throw Error('File sao lưu không hợp lệ.');const imported=[];for(const b of data.books){if(!b||typeof b.name!=='string'||!b.name.trim()||typeof b.audio!=='string'||!Array.isArray(b.cues)||b.cues.some(c=>!c||typeof c.text!=='string'||!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end<=c.start))throw Error('Dữ liệu bài nghe trong bản sao lưu không hợp lệ.');const blob=fromBase64(b.audio,b.type||'audio/mpeg');if(blob.size>200*1024*1024)throw Error('Có audio vượt quá 200 MB.');const duration=await durationOf(blob);if(b.cues.some(c=>c.start>=duration))throw Error('Phụ đề trong bản sao lưu nằm ngoài thời lượng audio.');const {audio:ignored,...book}=b;if(typeof book.caption!=='string')book.caption='';if(typeof book.filename!=='string')book.filename='audio';imported.push({book:{...book,id:crypto.randomUUID(),created:Date.now(),duration,size:blob.size,position:Math.max(0,Math.min(Number(book.position)||0,duration)),speed:[.5,.75,1,1.25,1.5,2].includes(book.speed)?book.speed:1,offset:Math.max(-120,Math.min(120,Number(book.offset)||0)),selected:Array.isArray(book.selected)?[...new Set(book.selected.filter(i=>Number.isInteger(i)&&i>=0&&i<book.cues.length))].sort((a,b)=>a-b):[]},blob});}await new Promise((resolve,reject)=>{const tx=db.transaction(['books','files'],'readwrite');for(const item of imported){tx.objectStore('books').put(item.book);tx.objectStore('files').put({id:item.book.id,blob:item.blob});}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Không đủ dung lượng.'));});await refresh();toast(`Đã khôi phục ${imported.length} bài. Các bài hiện có được giữ lại.`);}finally{$('import').disabled=false;$('backupFile').value='';}});
$('persist').onclick=()=>safe(async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Trình duyệt đã cho phép giữ dữ liệu lâu dài. Vẫn nên sao lưu.':'Trình duyệt chưa cấp quyền giữ dữ liệu lâu dài. Hãy dùng Sao lưu.');});
document.addEventListener('visibilitychange',()=>{if(document.hidden)safe(saveProgress);});
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('lang-nghe',1);r.onupgradeneeded=()=>{r.result.createObjectStore('books',{keyPath:'id'});r.result.createObjectStore('files',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Hãy đóng các tab Lắng nghe khác rồi tải lại.'));});db.onversionchange=()=>{db.close();toast('Dữ liệu đã thay đổi. Hãy tải lại trang.');};await refresh();tick();}catch(e){toast('Không mở được kho dữ liệu: '+e.message);$('add').disabled=$('emptyAdd').disabled=true;}
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;$('offline').textContent='✓ Giao diện đã sẵn sàng offline.';}).catch(()=>$('offline').textContent='Offline chưa sẵn sàng; bạn vẫn có thể dùng khi có mạng.');}else $('offline').textContent='Trình duyệt này không hỗ trợ offline.';
